script:
frappe.ui.form.on('User', {
	refresh: function(frm) {
		if (frm.is_new()) return;
		if (!frappe.model.can_create('Employee')) return;

		frm.add_custom_button(__('Create Employee'), function() {
			frappe.call({
				method: 'cos.cos_share.utils.user_employee.get_employee_for_user',
				args: { user: frm.doc.name },
				callback: function(r) {
					if (r.message) {
						frappe.set_route('Form', 'Employee', r.message);
					} else {
						frappe.call({
							method: 'cos.cos_share.utils.user_employee.get_employee_create_defaults',
							callback: function(dr) {
								var opts = dr.message || {};
								frappe.route_options = {
									user_id: frm.doc.name,
									first_name: frm.doc.first_name || '',
									last_name: frm.doc.last_name || '',
									middle_name: frm.doc.middle_name || '',
									company_email: frm.doc.email || '',
									cell_number: frm.doc.mobile_no || '',
									company: opts.company || '',
									gender: opts.gender || '',
									date_of_joining: opts.date_of_joining || frappe.datetime.get_today(),
								date_of_birth: opts.date_of_birth || ''
								};
								frappe.set_route('Form', 'Employee', 'new');
							}
						});
					}
				}
			});
		});
		}
	}
});
